// Slice run-log.jsonl and tool-timings.jsonl between OBS-MARKER commands.
const fs = require("fs");
const root = process.argv[2];
const read = (f) =>
  fs.readFileSync(`${root}/${f}`, "utf8").split("\n").filter((l) => l.trim()).map((l) => {
    try { return JSON.parse(l); } catch { return null; }
  }).filter(Boolean);

const log = read("run-log.jsonl");
const timings = read("tool-timings.jsonl");
console.log(`run-log rows: ${log.length}, timing rows: ${timings.length}`);
console.log(`sessions in log: ${[...new Set(log.map((r) => r.session_id))].join(", ")}`);

const isMarker = (r) => r.tool_name === "execute_pwsh" && JSON.stringify(r.tool_input || {}).includes("OBS-MARKER");
const markers = log.map((r, i) => (isMarker(r) ? i : -1)).filter((i) => i >= 0);
console.log(`marker rows (1-based): ${markers.map((i) => i + 1).join(", ")}`);

// Align timings to log rows: both are PostToolUse hooks, so check order by tool name.
const aligned = log.length === timings.length && log.every((r, i) => r.tool_name === timings[i].tool);
console.log(`timings aligned 1:1 with log rows: ${aligned}`);

const errorLike = /\b(error|exception|failed|traceback|denied|blocked)\b/i;
const labels = ["PR-01", "PR-02", "PR-03"];
for (let k = 0; k < 3 && k + 1 < markers.length; k++) {
  const start = markers[k] + 1, end = markers[k + 1]; // exclusive of both markers
  const rows = log.slice(start, end);
  console.log(`\n=== ${labels[k]}: log rows ${start + 1}-${end} (${rows.length} calls, markers excluded) ===`);
  const counts = {};
  rows.forEach((r) => (counts[r.tool_name] = (counts[r.tool_name] || 0) + 1));
  console.log("by tool: " + Object.entries(counts).map(([t, n]) => `${t} x${n}`).join(", "));
  rows.forEach((r, j) => {
    const inp = r.tool_input || {};
    const name = inp.name || inp.tool_id || inp.path || inp.targetFile || "";
    const resp = typeof r.tool_response === "string" ? r.tool_response : JSON.stringify(r.tool_response || "");
    const t = aligned ? timings[start + j].duration_ms : "?";
    const err = errorLike.test(resp) ? " <ERROR-LIKE TEXT>" : "";
    console.log(`  row ${start + j + 1}: ${r.tool_name} ${name} | ${t} ms | resp ${resp.length} chars${err}`);
  });
  if (aligned) {
    let slow = start;
    for (let i = start; i < end; i++) if (timings[i].duration_ms > timings[slow].duration_ms) slow = i;
    console.log(`slowest: row ${slow + 1} ${log[slow].tool_name} ${(log[slow].tool_input || {}).name || ""} ${timings[slow].duration_ms} ms`);
  }
  const sec = rows.filter((r) => r.tool_name === "invoke_sub_agent" && (r.tool_input || {}).name === "security-reviewer");
  console.log(`security-reviewer delegated: ${sec.length > 0 ? "Y" : "N"} (${sec.length} call)`);
  sec.forEach((r) => {
    const resp = typeof r.tool_response === "string" ? r.tool_response : JSON.stringify(r.tool_response);
    console.log("security-reviewer response starts: " + resp.slice(0, 260).replace(/\s+/g, " "));
  });
}

// Window tool-timings.jsonl by the four OBS-MARKER execute_pwsh calls (the last four execute_pwsh rows).
const fs = require("fs");
const root = process.argv[2];
const read = (f) =>
  fs.readFileSync(`${root}/${f}`, "utf8").split("\n").filter((l) => l.trim()).map((l) => {
    try { return JSON.parse(l); } catch { return null; }
  }).filter(Boolean);

const t = read("tool-timings.jsonl");
const pw = t.map((r, i) => (r.tool === "execute_pwsh" ? i : -1)).filter((i) => i >= 0);
const marks = pw.slice(-4); // PR-01 START, PR-01 END/PR-02 START, PR-02 END/PR-03 START, PR-03 END
console.log("marker timing rows:", marks.map((i) => `${i + 1}@${t[i].ended_at}`).join(" | "));
["PR-01", "PR-02", "PR-03"].forEach((label, k) => {
  const rows = t.slice(marks[k] + 1, marks[k + 1]);
  const slow = rows.reduce((a, b) => (b.duration_ms > a.duration_ms ? b : a), rows[0]);
  const byTool = {};
  rows.forEach((r) => (byTool[r.tool] = (byTool[r.tool] || 0) + 1));
  console.log(`\n${label}: ${rows.length} timed calls between markers (${t[marks[k]].ended_at} -> ${t[marks[k + 1]].ended_at})`);
  console.log("  by tool:", Object.entries(byTool).map(([n, c]) => `${n} x${c}`).join(", "));
  console.log(`  slowest: ${slow.tool} ${slow.duration_ms} ms (ended ${slow.ended_at})`);
  const top = [...rows].sort((a, b) => b.duration_ms - a.duration_ms).slice(0, 3);
  console.log("  top 3:", top.map((r) => `${r.tool} ${r.duration_ms} ms`).join("; "));
});

// What matched the error pattern in the app-conventions disclose_context responses?
const log = read("run-log.jsonl");
const re = /\b(error|exception|failed|traceback|denied|blocked)\b/gi;
const hits = new Set();
log.slice(39, 77).forEach((r) => {
  const s = typeof r.tool_response === "string" ? r.tool_response : JSON.stringify(r.tool_response || "");
  let m;
  while ((m = re.exec(s))) hits.add(`${r.tool_name}: "...${s.slice(Math.max(0, m.index - 30), m.index + 25).replace(/\s+/g, " ")}..."`);
});
console.log("\nerror-pattern matches in PR-01..PR-03 windows:");
hits.forEach((h) => console.log("  " + h));
